mapper.sql:
WHERE cs.is_active = #{filter.status}
AND csd.crm_support_pipeline_setting_id IN (
    SELECT crm_support_pipeline_setting_id
    FROM crm_support_pipeline_setting_egroups
    WHERE egroup_id IN (
        SELECT egroup_id
        FROM employee_egroups
        WHERE employee_id IN (SELECT id FROM employees WHERE user_id = #{userId})
    )
)

    AND csd.crm_support_pipeline_setting_id = #{filter.pipelineId}


    AND csd.crm_support_stag_id = #{filter.stageId}


    AND cs.assigned_to = #{filter.assignedTo}


    AND cs.created_by = #{filter.createdBy}


    AND cs.customer_id = #{filter.organizationId}


    AND DATE(cs.created) >= #{filter.dateFrom}


    AND DATE(cs.created) <= #{filter.dateTo}


    AND (
        cs.case_title LIKE CONCAT('%', #{filter.searchText}, '%')
        OR cs.code LIKE CONCAT('%', #{filter.searchText}, '%')
        OR customers.name LIKE CONCAT('%', #{filter.searchText}, '%')
        OR css.name LIKE CONCAT('%', #{filter.searchText}, '%')
    )

mapper.select:
SELECT 


GROUP BY cs.id
ORDER BY

    ${filter.orderBy}
    csd.crm_support_pipeline_setting_id ASC, csd.crm_support_stag_id ASC, cs.id DESC


    LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT 

WHERE cs.is_active IN (1, 2)
AND cs.id = #{id}

mapper.update:
UPDATE crm_supports
SET is_active = 2,
    modified = NOW(),
    modified_by = #{userId}
WHERE id = #{id}
AND is_active = 1

UPDATE crm_supports
SET code = #{code}
WHERE id = #{id}

UPDATE crm_support_details
SET is_active = 2
WHERE crm_support_id = #{supportId}
AND crm_support_pipeline_setting_id = #{pipelineId}

    AND crm_support_stag_id = #{stageId}

AND is_active = 1

UPDATE crm_support_details
SET description = #{description}
WHERE id = #{detailId}

UPDATE crm_support_details
SET description = #{description},
    is_convert = 1,
    converted = NOW(),
    converted_by = #{userId}
WHERE crm_support_id = #{supportId}

UPDATE crm_support_details
SET is_active = 0
WHERE id = #{detailId}

UPDATE crm_support_details
SET is_convert = 0
WHERE id = #{detailId}

UPDATE crm_supports
SET modified = NOW(),
    modified_by = #{userId}
WHERE id = #{supportId}
AND is_active = 1
